interface Env {
  API_SECRET: string;
}

function jsonResponse(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    const { pathname } = url;

    // Simple router
    if (pathname === '/api/health' && request.method === 'GET') {
      return jsonResponse({ status: 'ok', region: request.cf?.colo });
    }

    if (pathname === '/api/echo' && request.method === 'POST') {
      const body = await request.json();
      return jsonResponse({ echo: body });
    }

    if (pathname.startsWith('/api/')) {
      return jsonResponse({ error: 'Not found' }, 404);
    }

    // Pass non-API requests through to origin
    return fetch(request);
  },
};

interface Env {
  MEDIA_BUCKET: R2Bucket;
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    // Expected path: /media/<object-key>
    const key = url.pathname.replace('/media/', '');

    if (!key) {
      return new Response('Missing key', { status: 400 });
    }

    if (request.method === 'GET') {
      // Serve file from R2
      const object = await env.MEDIA_BUCKET.get(key);

      if (!object) {
        return new Response('Object not found', { status: 404 });
      }

      const headers = new Headers();
      object.writeHttpMetadata(headers);
      headers.set('etag', object.httpEtag);
      headers.set('Cache-Control', 'public, max-age=31536000');

      return new Response(object.body, { headers });
    }

    if (request.method === 'PUT') {
      // Upload file to R2
      await env.MEDIA_BUCKET.put(key, request.body, {
        httpMetadata: {
          contentType: request.headers.get('Content-Type') ?? 'application/octet-stream',
        },
      });

      return new Response(JSON.stringify({ key, uploaded: true }), {
        status: 201,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    return new Response('Method not allowed', { status: 405 });
  },
};
